package jp.tapmarker;
import java.io.*;import java.util.*;

public final class VirtualRecoveryReplayTest {
 static int checks;static Map<String,VirtualPresetProfileTest.Image> images=new LinkedHashMap<>();static Map<String,float[]> evidence=new HashMap<>();
 static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static final class Runtime {
  final boolean usagi;final String prefix;final PhaseEngine engine=new PhaseEngine();final VirtualPresetProfile profile;
  Runtime(boolean usagi)throws Exception{this.usagi=usagi;prefix=usagi?UsagiPreset.PREFIX:FarmPreset.P;Map<String,float[]> refs=VirtualPresetProfileTest.canonical(usagi?"tests/usagi-replay.bin":"tests/farm-replay.bin");if(usagi)UsagiPreset.install(engine,refs);else FarmPreset.install(engine,refs);profile=VirtualPresetProfile.install(engine,usagi?UsagiPreset.APP:FarmPreset.APP,evidence);AdCloseAutomaton.install(engine,usagi?UsagiPreset.APP:FarmPreset.APP);engine.strictRuntime=true;}
  Map<String,float[]> samples(VirtualPresetProfileTest.Image image){return samples(image.width,image.height,image);}
  Map<String,float[]> samples(int width,int height,RegionSampler.Pixels pixels){Map<String,float[]> result=new HashMap<>();for(PhaseEngine.Region region:engine.activeRegions()){if(AdCloseAutomaton.handles(region.id))AdCloseAutomaton.sample(region,width,height,pixels,result);else result.put(region.id,profile.handles(region.id)?profile.sample(region.id,width,height,pixels):RegionSampler.sample(width,height,region.bounds,pixels));}return result;}
  PhaseEngine.Watch event(String state,String name,long now){engine.enter(prefix+state,0);Map<String,float[]> s=samples(images.get(name));engine.observe(s,now);check(engine.poll()==null,"two fresh frames required: "+name+" in "+state);engine.observe(s,now+120);return engine.poll();}
  boolean home(String name){VirtualPresetProfileTest.Image image=images.get(name);PhaseEngine.Watch w=engine.rule(usagi?prefix+"return":prefix+"verify-home");return w.distance(profile.sample(image.width,image.height,image))<=w.threshold;}
 }
 static void load()throws Exception{
  try(DataInputStream in=new DataInputStream(new FileInputStream("tests/virtual-home-replay.bin"))){check(in.readInt()==2,"previous screenshot retained");for(int i=0;i<2;i++){new VirtualPresetProfileTest.Image(in);float[] ref=new float[in.readInt()];for(int k=0;k<ref.length;k++)ref[k]=in.readFloat();evidence.put(i==0?"usagi-home":"farm-home",ref);}}
  try(DataInputStream in=new DataInputStream(new FileInputStream("tests/virtual-recovery-replay.bin"))){check(in.readInt()==8,"eight current video crops");for(int i=0;i<8;i++)images.put(in.readUTF(),new VirtualPresetProfileTest.Image(in));String key=in.readUTF();float[] ref=new float[in.readInt()];for(int k=0;k<ref.length;k++)ref[k]=in.readFloat();evidence.put(key,ref);check(in.read()==-1,"complete recorded fixture");}
 }
 static void layoutEvidence()throws Exception{try(DataInputStream in=new DataInputStream(new FileInputStream("tests/adaptive-layout-anchor.bin"))){float[] ref=new float[in.readInt()];for(int k=0;k<ref.length;k++)ref[k]=in.readFloat();evidence.put("farm-layout-anchor",ref);}try(DataInputStream in=new DataInputStream(new FileInputStream("tests/adaptive-layout-home.bin"))){float[] ref=new float[in.readInt()];for(int k=0;k<ref.length;k++)ref[k]=in.readFloat();evidence.put("farm-layout-home",ref);}}
 static void mainCases()throws Exception{
  Runtime rabbit=new Runtime(true),farm=new Runtime(false);
  for(Runtime runtime:new Runtime[]{rabbit,farm}){check(runtime.engine.validate().isEmpty(),"virtual default graph valid");for(PhaseEngine.Region r:runtime.engine.activeRegions())check(!AdCloseAutomaton.handles(r.id)||(r.bounds[2]-r.bounds[0])*(r.bounds[3]-r.bounds[1])<=.015f,"main loop corner checks remain bounded");}
  VirtualPresetProfileTest.Image main=images.get("usagi-main");PhaseEngine.Watch home=rabbit.engine.rule(rabbit.prefix+"return");float[] actual=rabbit.profile.sample(main.width,main.height,main);
  float fine=0;for(int k=0;k<768;k++){float delta=actual[k]-home.reference[k];fine+=delta*delta/768;}check(fine>home.threshold,"v1.56 fine pixel comparison reproduces the supplied main-screen mismatch");
  check(rabbit.home("usagi-main"),"pixel alignment tolerance admits actual rabbit main screen");check(!rabbit.home("usagi-ad-left"),"advertisement cannot become rabbit main");
  PhaseEngine.Watch branch=rabbit.event("verify","usagi-main",100);check(branch!=null&&branch.nextPhase.equals(rabbit.prefix+"main"),"rabbit recovers into its main loop");
  branch=rabbit.event("main","usagi-main",100);check(branch==null,"506 rabbits creates no wrong event or purchase");
  for(String name:new String[]{"farm-main","farm-main-pressed"}){check(farm.home(name),"stable farm green anchor survives button motion: "+name);branch=farm.event("verify",name,100);check(branch!=null&&branch.nextPhase.equals(farm.prefix+"main"),"farm admits main and pressed frames");}
  branch=farm.event("main","farm-main",100);check(branch==null,"gray CM shovel is not falsely upgraded");
  branch=farm.event("main","farm-main-pressed",100);check(branch==null||branch.nextPhase.equals(farm.prefix+"upgrade-wait"),"available shovel never branches to reward or ad");
  for(String name:new String[]{"farm-ad-right","farm-ad-left","farm-reward","farm-reward-holdout"})check(!farm.home(name),"popup and ad block harvest: "+name);
  // Simulated scaling is a robustness check, not proof about native ImageReader pixels.
  for(Runtime runtime:new Runtime[]{rabbit,farm}){VirtualPresetProfileTest.Image im=images.get(runtime.usagi?"usagi-main":"farm-main-pressed");int width=720,height=Math.round(720*im.height/(float)im.width);RegionSampler.Pixels scaled=(x,y)->im.get(Math.min(im.width-1,(int)(x*im.width/(float)width)),Math.min(im.height-1,(int)(y*im.height/(float)height)));PhaseEngine.Watch gate=runtime.engine.rule(runtime.usagi?runtime.prefix+"return":runtime.prefix+"verify-home");check(gate.distance(runtime.profile.sample(width,height,scaled))<=gate.threshold,"normalized main recognition survives resized preview");}
 }
 static void rewardCases()throws Exception{
  Runtime farm=new Runtime(false);
  for(String name:new String[]{"farm-reward","farm-reward-holdout"}){
   for(String state:new String[]{"main","check","ad","verify"}){PhaseEngine.Watch branch=farm.event(state,name,7000);check(branch!=null&&branch.nextPhase.equals(farm.prefix+"reward"),"specific coin dialog overrides expired recovery in "+state+" / "+name);}
   PhaseEngine.Watch close=farm.event("reward",name,100);check(close!=null&&close.action==PhaseEngine.CENTER,"close button recognized: "+name);Map<String,float[]> samples=farm.samples(images.get(name));check(farm.engine.confirmsAction(close,farm.engine.current,farm.engine.epoch,samples),"close action still matches immediately before input");VirtualPresetProfileTest.Image im=images.get(name);float[] point=RegionMath.center(farm.engine.regions.get(close.regionId).bounds,im.width,im.height);check(point[0]>im.width*.40f&&point[0]<im.width*.60f&&point[1]>im.height*.565f&&point[1]<im.height*.613f,"tap is inside the actual individual close button");farm.engine.finish(close,300);check(farm.engine.current.equals(farm.prefix+"check"),"tap completion confirms the next display instead of starting harvest");
  }
  check(farm.event("reward","farm-main",100)==null,"main screen cannot substitute for close button");PhaseEngine.Watch exit=farm.event("reward","farm-ad-right",100);check(exit!=null&&AdCloseAutomaton.handles(exit.regionId)&&!exit.regionId.equals(FarmPreset.P+"close"),"visible ad exit interrupts reward handling without substituting for the reward Close");
  VirtualPresetProfileTest.Image reward=images.get("farm-reward-holdout");PhaseEngine.Region region=farm.engine.regions.get(farm.prefix+"close");int[] bounds=RegionMath.bounds(region.bounds,reward.width,reward.height);RegionSampler.Pixels missing=(x,y)->x>=bounds[0]&&x<bounds[2]&&y>=bounds[1]&&y<bounds[3]?0xff111111:reward.get(x,y);PhaseEngine.Watch close=farm.engine.rule(farm.prefix+"close-tap");check(close.distance(farm.profile.sample(region.id,reward.width,reward.height,missing))>close.threshold,"title alone cannot authorize an invisible close button");
 }
 static void ads()throws Exception{
  for(String[] row:new String[][]{{"usagi-ad-left","left"},{"farm-ad-right","right"},{"farm-ad-left","left"}}){Runtime runtime=new Runtime(row[0].startsWith("usagi"));VirtualPresetProfileTest.Image im=images.get(row[0]);String region=row[1].equals("left")?AdCloseAutomaton.LEFT:AdCloseAutomaton.RIGHT;PhaseEngine.Region roi=runtime.engine.regions.get(region);float[] point=AdCloseDetector.find(im.width,im.height,roi.bounds,im);check(point!=null,"actual visible ad X detected: "+row[0]);check(point[1]<im.height*.065f&&(row[1].equals("left")?point[0]<im.width*.1f:point[0]>im.width*.9f),"tap remains in the detected corner");
   PhaseEngine.Watch branch=runtime.event("ad",row[0],7000);check(branch!=null&&branch.action==PhaseEngine.CENTER&&branch.regionId.equals(region),"visible X wins over return-intent timeout");Map<String,float[]> s=runtime.samples(im);check(s.get(region+AdCloseAutomaton.POINT)!=null&&runtime.engine.confirmsAction(branch,runtime.engine.current,runtime.engine.epoch,s),"detected X provides both evidence and its actual center");runtime.engine.finish(branch,7200);check(runtime.engine.current.equals(runtime.prefix+"ad"),"closing ad keeps observing until game display is confirmed");
  }
  Runtime farm=new Runtime(false);for(String name:new String[]{"farm-main","farm-main-pressed","farm-reward-holdout","usagi-main"})for(String key:new String[]{AdCloseAutomaton.LEFT,AdCloseAutomaton.RIGHT}){VirtualPresetProfileTest.Image im=images.get(name);check(AdCloseDetector.find(im.width,im.height,farm.engine.regions.get(key).bounds,im)==null,"no invented X on game or reward: "+name);}
  int width=400,height=900;float[] roi={0,0,.10f,.065f};
  RegionSampler.Pixels plus=(x,y)->x>=12&&x<=28&&Math.abs(y-20)<=1||y>=12&&y<=28&&Math.abs(x-20)<=1?0xffffffff:0xff000000;check(AdCloseDetector.find(width,height,roi,plus)==null,"plus shape is not a close X");
  RegionSampler.Pixels light=(x,y)->x>=12&&x<=28&&y>=12&&y<=28&&(Math.abs(x-y)<=1||Math.abs(x+y-40)<=1)?0xff222222:0xffffffff;check(AdCloseDetector.find(width,height,roi,light)!=null,"dark X on a light background supplies an ad exit point");
 }
 static void budget(){RecoveryBudget a=new RecoveryBudget(),b=new RecoveryBudget();for(int i=0;i<3;i++)check(a.acquire(i*6000),"three scoped attempts accepted");check(!a.acquire(18000)&&a.remaining(18000)==8000,"fourth attempt starts cooldown rather than permanent stop");check(!a.acquire(20000)&&a.remaining(20000)==6000,"intent requests wait while observation remains possible");check(b.acquire(20000),"another screen has an independent budget");check(a.acquire(26000),"recovery resumes after cooldown");a.reset();check(a.acquire(26001)&&a.remaining(26001)==0,"known screen clears the recovery budget");}
 public static void main(String[] args)throws Exception{load();mainCases();rewardCases();ads();budget();System.out.println("VirtualRecoveryReplayTest: "+checks+" checks passed; recorded 6645 preview crops, sparse X detection and retry policy; actual Android inputs not tested");}
}
